        require(address(this).balance >= depositAmount);

        uint cBalBefore = address(c).balance;
        uint myBalBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetLogFile(newLog); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && address(c).balance == cBalBefore && c.balances(address(this)) == myBalBefore);
    }

    receive() external payable {}
